/**
 * Home: what the App is made of (`APP_DESCRIPTION`, SPEC K13), first in the sidebar after New chat, in
 * the words of the one who runs it. Where it runs and talks, in one line; its agents (the steward
 * marked), each with its model and tools; its components by what they are for, one opening at the side
 * with what it provides and needs and its config; and, folded, the wiring (`wiring.tsx`). The config
 * holds no secret: a component reads its secrets through `secrets` and its config names them at most,
 * and the API redacts a value that looks like one.
 */

import { ChatLines, Cloud, Cpu, Cube, Dashboard, Database, GitFork, Home, NavArrowRight, Sparks, Tools } from "iconoir-react";
import { type ReactNode, useState } from "react";
import { ValuePill } from "@/components/bui/Chip";
import EmptyState from "@/components/bui/EmptyState";
import LoadingState from "@/components/bui/LoadingState";
import { Page, PageLoading, Section } from "@/components/bui/Page";
import { RecordMark, RecordTag } from "@/components/bui/RecordsTable";
import { ErrorNote } from "@/components/pikit/error-note";
import { type ApiAgent, type ApiApp, useApi } from "@/lib/api";
import { assistantName } from "@/lib/names";
import { SidePanel, useShell } from "@/lib/shell";
import { defineView } from "@/lib/views";
import { type Component, type Group, groupsOf, placeOf, summaryOf } from "./overview";
import { ComponentDetails, ComponentPanel } from "./panel";
import { WiringSection } from "./wiring";

const GROUP_ICONS: Record<string, ReactNode> = {
  Channels: <ChatLines />,
  "Agents and models": <Sparks />,
  Tools: <Tools />,
  Data: <Database />,
  Integrations: <GitFork />,
  "Dashboard and admin": <Dashboard />,
  Platform: <Cloud />,
};

const CARD = "overflow-hidden rounded-card bg-surface shadow-card";

/** An agent: its name (the steward marked, a live one said so), what it is for, its model and its tools. */
function AgentCard({ agent }: { agent: ApiAgent }) {
  return (
    <article className={`${CARD} flex flex-col gap-3 p-4`}>
      <div className="flex min-w-0 items-center gap-2">
        <RecordMark name={agent.name} />
        <span className="min-w-0 truncate text-[14px] font-medium text-ink" title={agent.name}>
          {assistantName(agent.name)}
        </span>
        {agent.steward && (
          <span title="The project's steward: it knows what the project is made of, and operators ask it to change it">
            <ValuePill tone="accent">steward</ValuePill>
          </span>
        )}
        {agent.live === true && (
          <span title="Made in the dashboard: it is data, not the project's code">
            <ValuePill>live</ValuePill>
          </span>
        )}
      </div>
      {agent.description !== undefined && <p className="text-[12.5px] leading-relaxed text-ink-2">{agent.description}</p>}
      <div className="flex min-w-0 items-center gap-1.5 text-[12.5px] text-ink-2" title={agent.model}>
        <Cpu width={14} height={14} className="shrink-0 text-ink-3" aria-hidden />
        <span className="min-w-0 truncate font-mono text-[12px]">{agent.model}</span>
      </div>
      <div className="flex flex-wrap gap-1">
        {agent.tools.length === 0 ? (
          <span className="text-[12.5px] text-ink-3">No tools</span>
        ) : (
          agent.tools.map((tool) => (
            <RecordTag key={tool} title={tool}>
              {tool}
            </RecordTag>
          ))
        )}
      </div>
    </article>
  );
}

function AgentsSection({ agents }: { agents: ApiAgent[] | undefined }) {
  return (
    <Section title="Agents" meta={agents === undefined ? undefined : `${agents.length}`}>
      {agents === undefined ? (
        <div className="flex min-h-6 items-center">
          <LoadingState label="Reading the agents" variant="Dots" />
        </div>
      ) : agents.length === 0 ? (
        <div className={CARD}>
          <EmptyState icon={<Sparks />} title="No agent" hint="The App has no agent to talk to." />
        </div>
      ) : (
        <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
          {agents.map((agent) => (
            <AgentCard key={agent.name} agent={agent} />
          ))}
        </div>
      )}
    </Section>
  );
}

/** A kind of component: its rows, the open one pressed (and, below `lg`, its details under it). */
function GroupCard({ app, group, open, onOpen }: { app: ApiApp; group: Group; open: string | undefined; onOpen: (name: string) => void }) {
  return (
    <div className={`${CARD} mb-4 break-inside-avoid`}>
      <div className="flex items-center gap-2 border-b border-line px-4 py-2.5 text-ink-2 [&_svg]:size-[15px]">
        {GROUP_ICONS[group.title] ?? <Cube />}
        <h3 className="text-[12.5px] font-semibold text-ink">{group.title}</h3>
        <span className="text-[12px] text-ink-3 tabular-nums">{group.components.length}</span>
      </div>
      <ul className="p-1">
        {group.components.map((component) => {
          const pressed = component.name === open;
          return (
            <li key={component.name}>
              <button
                type="button"
                aria-pressed={pressed}
                onClick={() => onOpen(component.name)}
                className={`flex h-9 w-full items-center gap-2.5 rounded-[7px] px-3 text-left transition-colors duration-100 ${pressed ? "bg-hover-2" : "hover:bg-hover"}`}
              >
                <RecordMark name={component.name} />
                <span className="min-w-0 flex-1 truncate text-[13px] text-ink">{component.name}</span>
                {component.version !== undefined && <span className="shrink-0 font-mono text-[11.5px] text-ink-3">{component.version}</span>}
                <NavArrowRight width={14} height={14} strokeWidth={2} className={`shrink-0 text-ink-3 transition-transform duration-200 ${pressed ? "rotate-90 lg:rotate-0" : ""}`} aria-hidden />
              </button>
              {pressed && (
                <div className="border-y border-line bg-page px-4 py-4 lg:hidden">
                  <ComponentDetails app={app} component={component} />
                </div>
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function HomePage() {
  const { data: app, error } = useApi<ApiApp>("/app");
  const shell = useShell();
  const [open, setOpen] = useState<string>();

  if (error !== undefined) {
    return (
      <Page eyebrow="Home">
        <ErrorNote error={error} title="What the App is made of cannot be read" />
      </Page>
    );
  }
  if (app === undefined) return <PageLoading eyebrow="Home" />;

  const groups = groupsOf(app.components);
  const opened: Component | undefined = app.components.find((component) => component.name === open);

  return (
    <Page eyebrow="Home" title={`Runs on ${placeOf(app.target)}`} description={summaryOf(app, shell.agents?.length)}>
      <AgentsSection agents={shell.agents} />

      <Section title="Components" meta="by what they are for">
        <div className="columns-1 gap-4 md:columns-2">
          {groups.map((group) => (
            <GroupCard key={group.title} app={app} group={group} open={open} onOpen={(name) => setOpen(name === open ? undefined : name)} />
          ))}
        </div>
      </Section>

      <WiringSection app={app} />

      {opened !== undefined && (
        <SidePanel>
          <ComponentPanel app={app} component={opened} onClose={() => setOpen(undefined)} />
        </SidePanel>
      )}
    </Page>
  );
}

export default defineView({
  id: "home",
  title: "Home",
  icon: Home,
  order: 0,
  pages: [{ path: "/home", component: HomePage, fill: true }],
});

/**
 * What Home says of the App's composition (`ApiApp`), worked out here with no imports but types, so the
 * kit's tests read it as it is: its components by what they are for, the line that sums it up, and the
 * wiring worth a look (a capability with a choice of providers, a keyed one, one nobody provides, the
 * pipelines' stages).
 */

import type { ApiApp } from "../../lib/admin-api.ts";

export type Component = ApiApp["components"][number];

export interface Group {
  title: string;
  components: Component[];
}

/**
 * What a component is for: the first kind whose capabilities it provides (`storage.` is a family), else
 * whose prefix its name has. A channel provides only routes, so it is known by its name.
 */
const KINDS: { title: string; capabilities: string[]; prefixes: string[] }[] = [
  { title: "Channels", capabilities: [], prefixes: ["channel-"] },
  { title: "Agents and models", capabilities: ["agent.runtime", "model.provider", "agent.extension"], prefixes: ["runtime-", "provider-", "router-", "extension-", "agents-"] },
  { title: "Tools", capabilities: ["agent.tool"], prefixes: ["tool-"] },
  { title: "Data", capabilities: ["storage.", "conversations.registry", "settings", "outbound.queue"], prefixes: ["storage-", "conversations-"] },
  { title: "Integrations", capabilities: ["repo.github", "proposals"], prefixes: [] },
  { title: "Dashboard and admin", capabilities: ["admin.auth"], prefixes: ["admin-"] },
  { title: "Platform", capabilities: ["secrets", "wakeups", "execution"], prefixes: ["actors-", "deployment-", "secrets-", "execution-"] },
];
export const OTHER = "Other";

const provides = (component: Component, capabilities: string[]) =>
  component.provides.some((name) => capabilities.some((each) => (each.endsWith(".") ? name.startsWith(each) : name === each)));

export function kindOf(component: Component): string {
  const kind = KINDS.find((each) => provides(component, each.capabilities) || each.prefixes.some((prefix) => component.name.startsWith(prefix)));
  return kind?.title ?? OTHER;
}

/** The components by kind, in the kinds' order (Other last), each kind's by name; no empty kind. */
export function groupsOf(components: Component[]): Group[] {
  const titles = [...KINDS.map((kind) => kind.title), OTHER];
  return titles
    .map((title) => ({ title, components: components.filter((component) => kindOf(component) === title).sort((a, b) => a.name.localeCompare(b.name)) }))
    .filter((group) => group.components.length > 0);
}

/** Where the App runs, in words. */
export function placeOf(target: string): string {
  return target === "durable" ? "Cloudflare" : target === "server" ? "a server" : target;
}

/** The platforms its channels talk on, by the first word after `channel-` (`channel-telegram-webhook` is Telegram). */
export function channelsOf(components: Component[]): string[] {
  const names = components
    .filter((component) => component.name.startsWith("channel-"))
    .map((component) => component.name.slice("channel-".length).split("-")[0] ?? "")
    .filter((word) => word !== "")
    .map((word) => word.charAt(0).toLocaleUpperCase() + word.slice(1));
  return [...new Set(names)];
}

const plural = (count: number, one: string) => `${count} ${one}${count === 1 ? "" : "s"}`;
const list = (words: string[]) => (words.length <= 1 ? (words[0] ?? "") : `${words.slice(0, -1).join(", ")} and ${words.at(-1)}`);

/**
 * The App in one line: where it talks (its channels, and this dashboard), with how many agents (when
 * read) and tools, out of how many components.
 */
export function summaryOf(app: ApiApp, agents: number | undefined): string {
  const where = [...channelsOf(app.components), "this dashboard"];
  const tools = app.components.filter((component) => kindOf(component) === "Tools").length;
  const with_ = [...(agents === undefined ? [] : [plural(agents, "agent")]), plural(tools, "tool")];
  return `Talks on ${list(where)}, with ${list(with_)}: ${plural(app.components.length, "component")} in all.`;
}

/** Who provides `capability` for the App: its keys' providers, the one selected, or every provider. */
export function providersOf(app: ApiApp, capability: string): string[] {
  const found = app.capabilities[capability];
  if (found === undefined) return [];
  if (found.keys !== undefined && Object.keys(found.keys).length > 0) return [...new Set(Object.values(found.keys))];
  return found.selected !== undefined ? [found.selected] : found.providers;
}

/** The other components that use what `component` provides (requiring it, or using it when installed). */
export function usersOf(app: ApiApp, component: Component): string[] {
  return app.components
    .filter((other) => other.name !== component.name && [...other.requires, ...other.optional].some((capability) => component.provides.includes(capability)))
    .map((other) => other.name);
}

/**
 * A single capability more than one component provides, with the one the App uses. One every provider
 * of is used (`agent.tool`, a keyed one) is no choice.
 */
export interface Choice {
  capability: string;
  providers: string[];
  selected: string;
}

/** One key of a keyed capability (an `http.route`'s path) and who provides it. */
export interface Keyed {
  capability: string;
  key: string;
  provider: string;
}

/** A capability some components would use, which nothing provides. */
export interface Missing {
  capability: string;
  wantedBy: string[];
}

export interface Stage {
  id: string;
  priority?: number;
}

export interface Wiring {
  choices: Choice[];
  keyed: Keyed[];
  missing: Missing[];
  pipelines: { name: string; stages: Stage[] }[];
}

/** A pipeline's stage as the API gives it (`{ id, priority }`); anything else by its JSON. */
function stageOf(value: unknown): Stage {
  if (typeof value === "object" && value !== null && typeof (value as { id?: unknown }).id === "string") {
    const { id, priority } = value as { id: string; priority?: unknown };
    return typeof priority === "number" ? { id, priority } : { id };
  }
  return { id: JSON.stringify(value) };
}

export function wiringOf(app: ApiApp): Wiring {
  const capabilities = Object.entries(app.capabilities).sort(([a], [b]) => a.localeCompare(b));
  const choices = capabilities
    .flatMap(([name, capability]) => (capability.providers.length > 1 && capability.selected !== undefined ? [{ capability: name, providers: capability.providers, selected: capability.selected }] : []));
  const keyed = capabilities.flatMap(([name, capability]) =>
    Object.entries(capability.keys ?? {})
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, provider]) => ({ capability: name, key, provider })),
  );
  const wanted = new Map<string, string[]>();
  for (const component of app.components) {
    for (const capability of component.optional) {
      if ((app.capabilities[capability]?.providers.length ?? 0) > 0) continue;
      wanted.set(capability, [...(wanted.get(capability) ?? []), component.name]);
    }
  }
  const missing = [...wanted].sort(([a], [b]) => a.localeCompare(b)).map(([capability, wantedBy]) => ({ capability, wantedBy }));
  const pipelines = Object.entries(app.pipelines)
    .filter(([, stages]) => stages.length > 0)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, stages]) => ({ name, stages: stages.map(stageOf) }));
  return { choices, keyed, missing, pipelines };
}

/**
 * One component of the App, at the side (as a conversation's Context is): what it is for, what it
 * provides and to whom, what it needs and who gives it that, what it would use if installed, and its
 * config, the redacted JSON deployed with it (what an operator changes live is in Settings).
 */

import { Xmark } from "iconoir-react";
import type { ReactNode } from "react";
import CodeBlock from "@/components/bui/CodeBlock";
import { RecordTag, tagHue } from "@/components/bui/RecordsTable";
import type { ApiApp } from "@/lib/api";
import { type Component, kindOf, providersOf, usersOf } from "./overview";

/** A capability's tag, coloured by its family (`agent.`, `storage.`, …): the same everywhere. */
export const capabilityTag = (name: string) => (
  <RecordTag base={tagHue(name.split(".")[0] ?? name)} title={name}>
    {name}
  </RecordTag>
);

/** One part of the panel: a quiet label over what it says. */
function Part({ label, children }: { label: string; children: ReactNode }) {
  return (
    <section className="flex flex-col gap-2">
      <h3 className="text-[11.5px] font-medium text-ink-3">{label}</h3>
      {children}
    </section>
  );
}

const quiet = (text: string) => <p className="text-[12.5px] text-ink-3">{text}</p>;

/** Each capability, and on its right who gives it (or that nothing does). */
function Capabilities({ app, capabilities }: { app: ApiApp; capabilities: string[] }) {
  return (
    <ul className="flex flex-col gap-1.5">
      {capabilities.map((capability) => {
        const providers = providersOf(app, capability);
        return (
          <li key={capability} className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
            {capabilityTag(capability)}
            <span className={`min-w-0 truncate text-[12.5px] ${providers.length === 0 ? "text-ink-3" : "text-ink-2"}`} title={providers.join(", ")}>
              {providers.length === 0 ? "not installed" : `from ${providers.join(", ")}`}
            </span>
          </li>
        );
      })}
    </ul>
  );
}

export function ComponentDetails({ app, component }: { app: ApiApp; component: Component }) {
  const users = usersOf(app, component);
  const config = app.config[component.name];
  return (
    <div className="flex flex-col gap-5">
      <p className="text-[12.5px] text-ink-2">
        {kindOf(component)}
        {component.version !== undefined && <span className="font-mono text-ink-3"> · {component.version}</span>}
      </p>
      <Part label="Provides">
        {component.provides.length === 0 ? quiet("Nothing to the other components.") : <div className="flex flex-wrap gap-1">{component.provides.map(capabilityTag)}</div>}
        {users.length > 0 && <p className="text-[12.5px] text-ink-2">Used by {users.join(", ")}.</p>}
      </Part>
      <Part label="Needs">{component.requires.length === 0 ? quiet("Nothing.") : <Capabilities app={app} capabilities={component.requires} />}</Part>
      {component.optional.length > 0 && (
        <Part label="Uses if installed">
          <Capabilities app={app} capabilities={component.optional} />
        </Part>
      )}
      <Part label="Config">
        {config === undefined ? (
          quiet("None.")
        ) : (
          <CodeBlock filename="config.json" meta="redacted" code={JSON.stringify(config, null, 2)} />
        )}
        <p className="text-[12px] leading-relaxed text-ink-3">Set when the App is deployed. The values an operator changes live are in Settings.</p>
      </Part>
    </div>
  );
}

/** The panel at the side of the page (from `lg` up; below, the details open under the component's row). */
export function ComponentPanel({ app, component, onClose }: { app: ApiApp; component: Component; onClose: () => void }) {
  return (
    <aside aria-label={component.name} className="hidden w-[380px] shrink-0 flex-col overflow-hidden rounded-window border border-line bg-page lg:flex" style={{ animation: "fade-in 300ms ease both" }}>
      <div className="flex h-11 shrink-0 items-center justify-between gap-2 border-b border-line px-3 sm:pl-4">
        <span className="min-w-0 truncate text-[13px] font-semibold text-ink" title={component.name}>
          {component.name}
        </span>
        <button type="button" aria-label="Close the component" onClick={onClose} className="flex size-6 shrink-0 items-center justify-center rounded-[6px] text-ink-3 transition-colors duration-100 hover:bg-hover hover:text-ink">
          <Xmark width={15} height={15} strokeWidth={2} />
        </button>
      </div>
      <div key={component.name} className="min-h-0 flex-1 overflow-y-auto p-4" style={{ animation: "fade-in 200ms ease both" }}>
        <ComponentDetails app={app} component={component} />
      </div>
    </aside>
  );
}

/**
 * How the components are connected, folded until asked for (it is for whoever debugs the App): where
 * the App had a choice of providers and which it took, what nothing provides that a component would
 * use, each pipeline's stages in the order they run, and every key of a keyed capability (the routes)
 * with its provider.
 */

import { Cube, KeyframesCouple, NavArrowDown, Puzzle } from "iconoir-react";
import { type ReactNode, useState } from "react";
import { Section } from "@/components/bui/Page";
import RecordsTable, { type RecordColumn, RecordTag, TagList } from "@/components/bui/RecordsTable";
import type { ApiApp } from "@/lib/api";
import { type Choice, type Keyed, type Missing, wiringOf } from "./overview";
import { capabilityTag } from "./panel";

const name = (text: string) => <RecordTag title={text}>{text}</RecordTag>;

/** One part of the wiring: a small heading and what it says under it. */
function Part({ title, hint, children }: { title: string; hint: string; children: ReactNode }) {
  return (
    <div className="flex flex-col gap-2">
      <div className="flex flex-wrap items-baseline gap-x-2">
        <h3 className="text-[12.5px] font-semibold text-ink">{title}</h3>
        <span className="text-[12px] text-ink-3">{hint}</span>
      </div>
      {children}
    </div>
  );
}

const choiceColumns: RecordColumn<Choice>[] = [
  { key: "capability", label: "Capability", icon: <Puzzle />, width: 220, cell: (choice) => capabilityTag(choice.capability) },
  { key: "selected", label: "Used", icon: <Cube />, width: 200, cell: (choice) => name(choice.selected) },
  {
    key: "others",
    label: "Also installed",
    icon: <KeyframesCouple />,
    width: 260,
    cell: (choice) => <TagList tags={choice.providers.filter((each) => each !== choice.selected)} render={name} />,
  },
];

const missingColumns: RecordColumn<Missing>[] = [
  { key: "capability", label: "Capability", icon: <Puzzle />, width: 220, cell: (missing) => capabilityTag(missing.capability) },
  { key: "wanted", label: "Would be used by", icon: <Cube />, width: 420, cell: (missing) => <TagList tags={missing.wantedBy} render={name} /> },
];

const keyedColumns: RecordColumn<Keyed>[] = [
  { key: "capability", label: "Capability", icon: <Puzzle />, width: 180, sort: (a, b) => a.capability.localeCompare(b.capability), cell: (keyed) => capabilityTag(keyed.capability) },
  { key: "key", label: "Key", icon: <KeyframesCouple />, width: 340, sort: (a, b) => a.key.localeCompare(b.key), title: (keyed) => keyed.key, cell: (keyed) => <span className="truncate font-mono text-[12px]">{keyed.key}</span> },
  { key: "provider", label: "Provider", icon: <Cube />, width: 220, sort: (a, b) => a.provider.localeCompare(b.provider), cell: (keyed) => name(keyed.provider) },
];

export function WiringSection({ app }: { app: ApiApp }) {
  const [open, setOpen] = useState(false);
  const wiring = wiringOf(app);
  return (
    <Section
      title="Wiring"
      meta="how the components are connected"
      tools={
        <button
          type="button"
          aria-expanded={open}
          onClick={() => setOpen(!open)}
          className="flex h-7 items-center gap-1 rounded-[7px] px-2 text-[12.5px] font-medium text-ink-2 shadow-btn transition-colors duration-100 hover:bg-hover hover:text-ink"
        >
          {open ? "Hide" : "Show"}
          <NavArrowDown width={13} height={13} strokeWidth={2.2} className="transition-transform duration-300" style={{ transform: open ? "rotate(180deg)" : undefined }} />
        </button>
      }
    >
      {open && (
        <div className="flex flex-col gap-8" style={{ animation: "fade-up 320ms cubic-bezier(0.23,1,0.32,1) both" }}>
          <Part title="Choices" hint="a capability more than one component provides, and the one used">
            {wiring.choices.length === 0 ? (
              <p className="text-[12.5px] text-ink-3">None: every capability the App picks one provider for has only one.</p>
            ) : (
              <RecordsTable label="Capabilities with a choice of providers" columns={choiceColumns} rows={wiring.choices} rowKey={(choice) => choice.capability} empty={null} />
            )}
          </Part>
          <Part title="Not installed" hint="what some components would use, if a component provided it">
            {wiring.missing.length === 0 ? (
              <p className="text-[12.5px] text-ink-3">Nothing: every capability a component would use is provided.</p>
            ) : (
              <RecordsTable label="Capabilities nothing provides" columns={missingColumns} rows={wiring.missing} rowKey={(missing) => missing.capability} empty={null} />
            )}
          </Part>
          <Part title="Pipelines" hint="each one's stages, in the order they run">
            {wiring.pipelines.length === 0 ? (
              <p className="text-[12.5px] text-ink-3">No pipeline has a stage.</p>
            ) : (
              <div className="records-shell divide-y divide-line">
                {wiring.pipelines.map((pipeline) => (
                  <div key={pipeline.name} className="flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3">
                    <span className="w-40 shrink-0 font-mono text-[12.5px] text-ink">{pipeline.name}</span>
                    <ol className="flex min-w-0 flex-wrap items-center gap-1.5">
                      {pipeline.stages.map((stage, i) => (
                        <li key={`${stage.id}-${i}`} className="flex items-center gap-1.5" title={stage.priority === undefined ? stage.id : `${stage.id}, priority ${stage.priority}`}>
                          {i > 0 && <span className="text-ink-3" aria-hidden>→</span>}
                          <span className="inline-flex h-6 items-center gap-1.5 rounded-chip bg-inset px-2 text-[12px] text-ink-2 shadow-hairline">
                            <span className="font-mono text-[11px] text-ink-3 tabular-nums">{i + 1}</span>
                            <span className="font-mono">{stage.id}</span>
                          </span>
                        </li>
                      ))}
                    </ol>
                  </div>
                ))}
              </div>
            )}
          </Part>
          <Part title="Keys" hint="each key of a keyed capability (a route, a command) and its provider">
            {wiring.keyed.length === 0 ? (
              <p className="text-[12.5px] text-ink-3">No keyed capability.</p>
            ) : (
              <RecordsTable label="Keyed capabilities" columns={keyedColumns} rows={wiring.keyed} rowKey={(keyed) => `${keyed.capability} ${keyed.key}`} maxHeight={420} empty={null} />
            )}
          </Part>
        </div>
      )}
    </Section>
  );
}
